	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc("GET "+options.BaseURL+"/{$}", wrapper.GetRoot)
	m.HandleFunc("GET "+options.BaseURL+"/auth/code", wrapper.GetAuthCode)
	m.HandleFunc("GET "+options.BaseURL+"/events", wrapper.GetEvents)
	m.HandleFunc("POST "+options.BaseURL+"/player/add_to_queue", wrapper.PlayerAddToQueue)
	m.HandleFunc("POST "+options.BaseURL+"/player/next", wrapper.PlayerNext)
	m.HandleFunc("POST "+options.BaseURL+"/player/output", wrapper.PlayerOutput)
	m.HandleFunc("POST "+options.BaseURL+"/player/pause", wrapper.PlayerPause)
	m.HandleFunc("POST "+options.BaseURL+"/player/play", wrapper.PlayerPlay)
	m.HandleFunc("POST "+options.BaseURL+"/player/playpause", wrapper.PlayerPlayPause)
	m.HandleFunc("POST "+options.BaseURL+"/player/prev", wrapper.PlayerPrev)
	m.HandleFunc("POST "+options.BaseURL+"/player/repeat_context", wrapper.PlayerRepeatContext)
	m.HandleFunc("POST "+options.BaseURL+"/player/repeat_track", wrapper.PlayerRepeatTrack)
	m.HandleFunc("POST "+options.BaseURL+"/player/resume", wrapper.PlayerResume)
	m.HandleFunc("POST "+options.BaseURL+"/player/seek", wrapper.PlayerSeek)
	m.HandleFunc("POST "+options.BaseURL+"/player/shuffle_context", wrapper.PlayerShuffleContext)
	m.HandleFunc("POST "+options.BaseURL+"/player/stop", wrapper.PlayerStop)
	m.HandleFunc("GET "+options.BaseURL+"/player/volume", wrapper.PlayerGetVolume)
	m.HandleFunc("POST "+options.BaseURL+"/player/volume", wrapper.PlayerSetVolume)
	m.HandleFunc("POST "+options.BaseURL+"/set_device_name", wrapper.SetDeviceName)
	m.HandleFunc("GET "+options.BaseURL+"/status", wrapper.GetStatus)
